input.command:
chcp 65001 | Out-Null; [Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $ErrorActionPreference = 'Stop'
# L1 deletes via git rm / Remove-Item
git rm -f -- "2026-07-27-automatic-trading-v2-final-rebuild-plan.md" "v2-runtime-final-snapshot.md" "v2-runtime-final.png" "services/strategy_library/ensemble/service.py.backup"
# Optional local junk
@(
  '.dev-api.err.log','.dev-api.out.log','.dev-vite.err.log','.dev-vite.out.log',
  'artifacts_strategy_backfill.log','.local_paper_console.pre-0015-20260727-1610.db'
) | ForEach-Object { if (Test-Path $_) { Remove-Item -LiteralPath $_ -Force; Write-Host "removed local $_" } }
# Empty artifact dirs if present
Get-ChildItem -Path 'artifacts/strategy_refactor' -Directory -ErrorAction SilentlyContinue | Where-Object {
  $_.Name -like 'proposal-research-20260731-*' -or $_.Name -eq 'history'
} | ForEach-Object {
  $empty = @(Get-ChildItem -LiteralPath $_.FullName -Force -Recurse -ErrorAction SilentlyContinue | Where-Object { -not $_.PSIsContainer })
  if ($empty.Count -eq 0) {
    # only remove truly empty leaf dirs under history or empty proposal dirs
  }
}
Write-Host 'L1 delete done'
git status --short | Select-Object -First 30

chcp 65001 | Out-Null; [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
Write-Host '=== force-tracked artifacts ==='
git ls-files 'artifacts/**' | Select-Object -First 40
Write-Host '=== scripts not in SUPPORTED (sample) ==='
$supported = Get-Content scripts/SUPPORTED.md -Raw
Get-ChildItem scripts -File -Filter '*.py' | Where-Object { $_.Name -notmatch '^__' } | ForEach-Object {
  $n = $_.Name
  if ($supported -notmatch [regex]::Escape($n) -and $n -notmatch '^archive') { $n }
} | Sort-Object
Write-Host '=== docs/audits ==='
Get-ChildItem docs/audits -ErrorAction SilentlyContinue | Select-Object Name
Write-Host '=== local junk sizes ==='
@('.pytest-report.xml','ai_quant_research_platform.egg-info','.strategy_refactor_history.db','.local_paper_console.db','.local_runtime_ledger.db') | ForEach-Object {
  if (Test-Path $_) { $i = Get-Item $_; if ($i.PSIsContainer) { $s=(Get-ChildItem $_ -Recurse -File -EA SilentlyContinue | Measure-Object Length -Sum).Sum } else { $s=$i.Length }; Write-Host ("{0:N1} MB  {1}" -f ($s/1MB), $_) }
}
Write-Host '=== logs top ==='
if (Test-Path logs) { Get-ChildItem logs -File | Sort-Object Length -Descending | Select-Object -First 15 Name, @{N='MB';E={[math]::Round($_.Length/1MB,2)}} }

chcp 65001 | Out-Null; [Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $ErrorActionPreference = 'Stop'

New-Item -ItemType Directory -Force -Path 'docs/archive/2026-07/session-reports' | Out-Null
New-Item -ItemType Directory -Force -Path 'docs/archive/2026-07/strategy-layer' | Out-Null
New-Item -ItemType Directory -Force -Path 'scripts/archive/2026-08-ops-checks' | Out-Null

# Remaining docs root session / handoff / status reports
$docsSession = @(
  'BINANCE_AUTO_TRADING_SUMMARY_2026-07-25.md',
  'DRAWDOWN_FIX_CHECKLIST.md',
  'EXIT-POLICY-VALIDATION-SUMMARY.md',
  'ORDER_SYNC_EXPLANATION.md',
  'SYSTEM_STATUS_CONFIRMATION.md'
)
foreach ($f in $docsSession) {
  if (Test-Path "docs/$f") { git mv -f "docs/$f" "docs/archive/2026-07/session-reports/$f" }
}

$docsStrategy = @(
  '2026-07-27-crypto-quant-strategy-v2-refactor-plan.md',
  'stage1-pandas-ta-adapter-acceptance.md',
  'strategy-layer-refactor-handoff.md',
  'strategy-layer-refactor-progress-report.md'
)
foreach ($f in $docsStrategy) {
  if (Test-Path "docs/$f") { git mv -f "docs/$f" "docs/archive/2026-07/strategy-layer/$f" }
}

# Ops one-off scripts (no tests / not launcher / not run_tool_tasks deps)
$ops = @(
  'final_acceptance_check.py','final_drawdown_check.py',
  'list_tables.py','check_db_simple.py','check_positions.py','check_overnight.py',
  'find_btc_long_orders.py','debug_manual_pnl_calc.py','investigate_drawdown.py',
  'investigate_large_limit_order.py','investigate_large_limit_order2.py',
  'match_081_orders_to_records.py','show_contract_error.py',
