  'diagnose_restart_period.py','analyze_execution_chain.py','analyze_reduce_only_pattern.py',
  'check_binance_open_orders_direct.py','check_binance_positions.py','check_binance_raw_open_orders.py',
  'check_decision_snapshots.py','check_direct_drawdown_rejection.py','check_exchange_account_value.py',
  'check_fix_status.py','check_order_details.py','check_orders_with_run_context.py',
