$moved = 0
foreach ($f in $ops) {
  if (Test-Path "scripts/$f") { git mv -f "scripts/$f" "scripts/archive/2026-08-ops-checks/$f"; $moved++ }
}
Write-Host "ops scripts moved: $moved"

# Untrack force-added log under artifacts (keep file locally if present)
if (git ls-files --error-unmatch 'artifacts/strategy_refactor/history/20260729-0000Z/backfill.log' 2>$null) {
  git rm --cached -f 'artifacts/strategy_refactor/history/20260729-0000Z/backfill.log'
  Write-Host 'untracked backfill.log'
}

# Remove empty proposal dirs
Get-ChildItem 'artifacts/strategy_refactor' -Directory -EA SilentlyContinue | Where-Object {
  $_.Name -like 'proposal-research-*'
} | ForEach-Object {
  if (@(Get-ChildItem $_.FullName -Force -EA SilentlyContinue).Count -eq 0) {
    Remove-Item -LiteralPath $_.FullName -Force
    Write-Host "removed empty $($_.Name)"
  }
}
if (Test-Path 'artifacts/strategy_refactor/history/20260730-0800Z') {
  if (@(Get-ChildItem 'artifacts/strategy_refactor/history/20260730-0800Z' -Force -EA SilentlyContinue).Count -eq 0) {
    Remove-Item -LiteralPath 'artifacts/strategy_refactor/history/20260730-0800Z' -Force
    Write-Host 'removed empty history/20260730-0800Z'
  }
}

# Local regenerable junk
if (Test-Path 'ai_quant_research_platform.egg-info') { Remove-Item -Recurse -Force 'ai_quant_research_platform.egg-info'; Write-Host 'removed egg-info' }
if (Test-Path 'scripts/_tmp_refscan.py') { Remove-Item -Force 'scripts/_tmp_refscan.py'; Write-Host 'removed tmp scanner' }

Write-Host 'DONE batch'
git status --short | Measure-Object -Line | Select-Object -ExpandProperty Lines
